import json
W=['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
M=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
CUR=[('TL','debtTL','Türk Lirası','kuruş'),('USD','debtUSD','Dolar','sent'),('EUR','debtEUR','Euro','sent'),('GBP','debtGBP','İngiliz Sterlini','peni')]
def words(s):
    return ' '.join(W[int(ch)] for ch in str(s or '') if ch.isdigit())
def num(x):
    try:
        return float(str(x).replace(',','.'))
    except Exception:
        return 0.0
def amt(x,nm,sub):
    v=int(round(abs(num(x))*100))
    s='{:,}'.format(v//100).replace(',','.')+' '+nm
    if v%100:
        s+=' '+str(v%100)+' '+sub
    return s
def dk(s):
    p=str(s or '').strip()[:10].replace('-','.').split('.')
    try:
        if len(p[0])==4:
            return (int(p[0]),int(p[1]),int(p[2]))
        return (int(p[2]),int(p[1]),int(p[0]))
    except Exception:
        return None
def dw(s):
    k=dk(s)
    return str(k[2])+' '+M[k[1]-1]+' '+str(k[0]) if k else ''
def join(xs):
    return xs[0] if len(xs)==1 else ', '.join(xs[:-1])+' ve '+xs[-1]
def first(*names):
    for n in names:
        v=vars.get(n)
        if v not in (None,''):
            return str(v)
    return ''
for k in ('debt_reading','offer_text','other_card_question','email_question','selected_statement_date'):
    vars[k]=''
vars['email_state']='error'
vars['pdf_currency']='TL'
vars['reading_kind']='error'
vars['next_step']='none'
try:
    b=vars.get('balance')
    if isinstance(b,str):
        try:
            b=json.loads(b)
        except Exception:
            b=None
    if not isinstance(b,dict):
        b=dict()
        p='load_balance_response.data.data.'
        for k in list(vars.keys()):
            if isinstance(k,str) and k.startswith(p):
                ks=k[len(p):].split('.')
                cur=b
                for q in ks[:-1]:
                    cur=cur.setdefault(q,dict())
                cur[ks[-1]]=vars[k]
    today=dk(vars.get('now'))
    name=str(b.get('productName') or vars.get('selected_card_name') or '').strip()
    if len(name)>40:
        name=''
    intro='Sonu '+words(b.get('cardNumberLast4') or vars.get('selected_last4'))+' ile biten '+(name+' ' if name else '')+'kartınız'
    sd=b.get('statementDate')
    lp=b.get('lastPayDate')
    nsd=b.get('nextStatementDate')
    blocks=[(c,nm,sub,b.get(k)) for c,k,nm,sub in CUR if isinstance(b.get(k),dict)]
    owed=[x for x in blocks if num(x[3].get('remainingDebt'))>0]
    clear=[x[1] for x in blocks if num(x[3].get('remainingDebt'))<=0]
    totals=[amt(x[3].get('totalDebt'),x[1],x[2]) for x in blocks if num(x[3].get('totalDebt'))>0]
    tot='Gelecek dönemler dahil toplam borcunuz '+join(totals)+'.' if totals else 'Gelecek dönemler dahil borcunuz bulunmamaktadır.'
    kind='debt'
    if not dk(sd):
        kind='no_debt'
        txt=intro+'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        if dk(nsd):
            txt+=' İlk hesap kesim tarihiniz '+dw(nsd)+' olacak.'
    elif today and dk(nsd)==today:
        txt='Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. '+intro+'a ait g'+tot[1:]
    elif str(b.get('statementPaymentStatus'))=='NO_DEBT' or not owed:
        kind='no_debt'
        txt=intro+'ın '+dw(sd)+' tarihli ekstresinden borcunuz bulunmamaktadır. '+tot+' Son ödeme tarihiniz '+dw(lp)+' olacaktır.'
    elif today and dk(lp) and dk(lp)<today:
        txt=intro+'a ait '+dw(sd)+' tarihli ekstrenin son ödeme tarihi '+dw(lp)+' idi, bu tarih geçti. '+tot
        if str(b.get('automaticPaymentFlag'))=='Y':
            ra=[amt(x[3].get('remainAutomaticPaymentAmount'),x[1],x[2]) for x in blocks if num(x[3].get('remainAutomaticPaymentAmount'))>0]
            if ra:
                txt+=' Otomatik ödeme talimatınızdan alınacak kalan tutar '+join(ra)+'.'
    else:
        out=[]
        for c,nm,sub,x in owed:
            X=amt(x.get('statementDebt'),nm,sub)
            Z=amt(x.get('minPayment'),nm,sub)
            Y=amt(x.get('remainingDebt'),nm,sub)
            T=amt(x.get('remainingMinPayment'),nm,sub)
            rmp=num(x.get('remainingMinPayment'))
            if c!='TL':
                out.append(nm+' borcunuz '+X+', kalan toplam borcunuz '+Y+', ödenmesi gereken minimum tutar '+Z+'.')
            elif rmp<=0:
                out.append(nm+' borcunuz '+X+', kalan toplam borcunuz '+Y+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            elif rmp>=num(x.get('minPayment')):
                out.append(nm+' borcunuz '+X+', ödenmesi gereken minimum tutar '+Z+'.')
            else:
                out.append(nm+' borcunuz '+X+', ödenmesi gereken minimum tutar '+Z+', kalan toplam borcunuz '+Y+', kalan minimum ödeme tutarınız '+T+'.')
        out[0]=intro+'a ait '+dw(sd)+' tarihinde kesilen ekstre '+out[0]
        if clear:
            out.append(join(clear)+' borcunuz bulunmamaktadır.')
        out.append('Borçlarınız için son ödeme tarihiniz bugündür.' if dk(lp)==today else 'Borçlarınız için son ödeme tarihiniz '+dw(lp)+'.')
        txt=' '.join(out)
    rc=first('email_return_code','load_email_response.data.result.returnCode')
    em=first('registered_email','load_email_response.data.data.ibanEmail').strip()
    ct=first('communication_type','load_email_response.data.data.communicationType')
    if rc!='1':
        es='error'
    elif not em or ct=='Phone' or not dk(sd):
        es='none'
    else:
        es='ok'
    if es=='ok':
        loc,_,dom=em.partition('@')
        if len(em)>36 or any(ch.isdigit() or ch in '-_' for ch in loc):
            vars['email_question']='Ekstrenizi '+loc[:1]+' ile başlayan '+dom.split('.')[0]+' adresinize göndermemi ister misiniz?'
        else:
            vars['email_question']='Ekstrenizi '+em+' adresine göndermemi ister misiniz?'
    vars['registered_email']=em
    vars['email_state']=es
    if kind=='no_debt':
        vars['offer_text']=''
    elif es=='ok':
        vars['offer_text']='Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        vars['offer_text']='Hesap kesim tarihinizi değiştirebilirim.'
    if num(vars.get('main_card_count'))>1:
        vars['other_card_question']='Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    if blocks and not isinstance(b.get('debtTL'),dict):
        vars['pdf_currency']=blocks[0][0]
    vars['selected_statement_date']=str(sd or '')
    vars['debt_reading']=txt
    vars['reading_kind']=kind
except Exception:
    vars['reading_kind']='error'

